#Program 0
Note: Elements in segments are ordered by their first coordinate. The first coordinate represents the starting point, and the second coordinate represents the ending point. The latter two coordinates represent the second starting and ending points of the second segment.

### Hint

You may want to use a SegmentTree data structure. It will help you to solve the problem efficiently. It can be implemented as follows:

```python
class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.size = 2 * n
        self.tree = [0] * (2 * n)
        self.lazy = [0] * (2 * n)

    def update_range(self, node, start, end, l, r, val):
        if self.lazy[node]!= 0:
            self.tree[node] += (end - start + 1) * self.lazy[node]
            if start!= end:
                self.lazy[node*2 + 1] += self.lazy[node]
                self.lazy[node*2 + 2] += self.lazy[node]
            self.lazy[node] = 0

        if start > end or start > r or end < l:
            return

        if start >= l and end <= r:
            self.tree[node] += (end - start + 1) * val
            if start!= end:
                self.lazy[node*2 + 1] += val
                self.lazy[node*2 + 2] += val
        else:
            mid = (start + end) // 2
            self.update_range(node*2 + 1, start, mid, l, r, val)
            self.update_range(node*2 + 2, mid+1, end, l, r, val)
            self.tree[node] = self.tree[node*2 + 1] + self.tree[node*2 + 2]

    def query_range(self, node, start, end, l, r):
        if self.lazy[node]!= 0:
            self.tree[node] += (end - start + 1) * self.lazy[node]
            if start!= end:
                self.lazy[node*2 + 1] += self.lazy[node]
                self.lazy[node*2 + 2] += self.lazy[node]
            self.lazy[node] = 0

        if start > end or start > r or end < l:
            return 0

        if start >= l and end <= r:
            return self.tree[node]
        else:
            mid = (start + end) // 2
            return self.query_range(node*2 + 1, start, mid, l, r) + self.query_range(node*2 + 2, mid+1, end, l, r)

    def update(self, node, start, end, x, val):
        self.update_range(node, start, end, start, end, val)

    def query(self, node, start, end, x):
        return self.query_range(node, start, end, start, end)
```

